#!/usr/bin/env bash

# Print the Homebrew formula for a release: brew-formula.sh <tag> <checksums.txt>
# The release job writes it to deepak-science/homebrew-tap as Formula/kest.rb.

set -euo pipefail

tag="${1:?usage: brew-formula.sh <tag> <checksums.txt>}"
sums="${2:?usage: brew-formula.sh <tag> <checksums.txt>}"
base="https://github.com/deepak-science/kestrel/releases/download/${tag}"

sha() {
  local s
  s=$(awk -v f="$1" '$2 == f { print $1 }' "$sums")
  [[ -n $s ]] || {
    echo >&2 "no checksum for $1 in $sums"
    exit 1
  }
  echo "$s"
}

cat <<EOF
# Generated by kestrel's release workflow (scripts/brew-formula.sh); edits here are overwritten.
class Kest < Formula
  desc "Per-project wrapper for helm and terraform"
  homepage "https://github.com/deepak-science/kestrel"
  url "${base}/kest-darwin-arm64"
  version "${tag#v}"
  sha256 "$(sha kest-darwin-arm64)"
  license "Apache-2.0"

  depends_on arch: :arm64
  depends_on :macos

  resource "kestci" do
    url "${base}/kestci-darwin-arm64"
    sha256 "$(sha kestci-darwin-arm64)"
  end

  def install
    bin.install "kest-darwin-arm64" => "kest"
    resource("kestci").stage { bin.install "kestci-darwin-arm64" => "kestci" }
    # Bare downloads arrive non-executable, and completions are generated before brew's cleaner would fix that.
    chmod 0755, [bin/"kest", bin/"kestci"]
    generate_completions_from_executable(bin/"kest", "completion")
    generate_completions_from_executable(bin/"kestci", "completion")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/kest --version")
  end
end
EOF
